import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BUOFcz_J.js";const u=JSON.parse('{"title":"Contract and call-boundary acceptance","description":"","frontmatter":{},"headers":[],"relativePath":"records/contract-acceptance.md","filePath":"records/contract-acceptance.md"}'),s={name:"records/contract-acceptance.md"};function n(d,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<div class="warning custom-block"><p class="custom-block-title">Historical record</p><p>This page records what happened on a date, with its observed failures and limits. It is not a requirement for the current implementation. Current behaviour is in <a href="/Rho/docs/reference/status">Status</a>.</p></div><h1 id="contract-and-call-boundary-acceptance" tabindex="-1">Contract and call-boundary acceptance <a class="header-anchor" href="#contract-and-call-boundary-acceptance" aria-label="Permalink to &quot;Contract and call-boundary acceptance&quot;">​</a></h1><p>What was actually executed for the contract, type and call-boundary work, on which identities, and what it does not establish. <a href="/Rho/docs/reference/status">Status</a> summarises; this page keeps the observations and their limits.</p><h2 id="identities" tabindex="-1">Identities <a class="header-anchor" href="#identities" aria-label="Permalink to &quot;Identities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Identity</th></tr></thead><tbody><tr><td>Application source</td><td><code>YuLab-SMU/Rho</code> <code>480ac6f5d65f7d44b6c0c2617c2531670b30d772</code> (tree <code>b63e0b31…</code>)</td></tr><tr><td>Component source</td><td><code>YuLab-SMU/Rho-plugins</code> <code>18252d2ddc5250845402a13098e9eb467156cbbf</code></td></tr><tr><td>Core binary</td><td><code>YuLab-SMU/Rho-core</code> <code>ebe351043e74529ccf49960c0b07c805d1e50c07</code>, unchanged</td></tr><tr><td>Packed artifact</td><td><code>rho-workspace-local-0.4.0.tgz</code>, SHA-256 <code>35400ccfdd64bf2b27410d0b7ec3749ca8b815729b8308f0bd53f9cae1d6dd6a</code>, 4,048 files</td></tr><tr><td>Platform</td><td>macOS arm64, Node 22.22.3, R 4.5.2, Chrome 155.0.8059.84</td></tr></tbody></table><p>The artifact was assembled by <code>npm run pack:local</code> from the committed sources above; no working-tree changes were included.</p><h2 id="source-and-installed-columns" tabindex="-1">Source and installed columns <a class="header-anchor" href="#source-and-installed-columns" aria-label="Permalink to &quot;Source and installed columns&quot;">​</a></h2><p><code>scripts/matrix.mjs --install …</code> ran three journeys against a source build and against a copy of the packed artifact installed outside the checkouts (<code>npm install --offline</code> of the tarball). Every row passed:</p><table tabindex="0"><thead><tr><th>Journey</th><th>Source</th><th>Installed</th><th>Observed</th></tr></thead><tbody><tr><td>person (<code>person-files-acceptance</code>)</td><td>passed</td><td>passed</td><td>9 checks: shell loads at 1440/768/390 without horizontal overflow, the real folder is listed, a subfolder opens, button and keyboard save real Unicode bytes at all three widths, a refreshed tab reads the saved document, another writer updates the tab through the owner revision, an external disk write refuses save and preserves both disk and buffer, the tab stays refused parent paths, registration and execution, no page errors</td></tr><tr><td>execution/MCP (<code>execution-acceptance</code>)</td><td>passed</td><td>passed</td><td>5 checks: four-tool discovery resolves, edits and conditionally saves through stdio MCP; the original request completes through observation with no resubmission; <code>artifact.check</code> returns a verified owner-state reference that binds directly; the browser decodes the real 640×420 PNG with owner-sized 4096-byte pages at three widths; refresh renders the same version without CSP errors or new native execution. Exactly one Host start and one native dispatch, zero model calls</td></tr><tr><td>U1 (<code>ui-acceptance</code>)</td><td>passed</td><td>passed</td><td>23 checks across 1600/1280/1024/768/390, zero Host starts and zero native dispatches</td></tr></tbody></table><p>The installed copy&#39;s own artifact was checked directly: all 86 packaged operation files matched their recorded byte count and SHA-256, the shared definitions file matched, and the installed service reported the same 86 operations, <code>apiVersion 2.0</code>, <code>schemaVersion 2</code> and nine selected owners.</p><h2 id="recovery-with-a-real-host-and-r" tabindex="-1">Recovery, with a real Host and R <a class="header-anchor" href="#recovery-with-a-real-host-and-r" aria-label="Permalink to &quot;Recovery, with a real Host and R&quot;">​</a></h2><p><code>scripts/recovery-acceptance.mjs</code> on a disposable project passed 7 checks:</p><ul><li>a real partial snapshot has four observed rows and no completion declaration;</li><li>the concurrent-action limit rejects new work while preserving the original request;</li><li>closing observation, the view and the external binding does not cancel the analysis;</li><li>rebinding observes the original task without submitting it;</li><li>Host loss retains partial data, the original identity, an unknown outcome and an unconfirmed cancellation;</li><li>the partial export restores bytes and provenance without starting a Host;</li><li>an explicit cancel acknowledgement and an independently observed process-group release remain separate facts.</li></ul><p>Its R fixture previously could not run at all: the producer now pre-creates the declared output directory, so the fixture&#39;s <code>stopifnot(dir.create(out))</code> returned false and aborted before writing any artifact. The fixture tolerates an existing directory now, which is what makes the observations above real rather than assumed. The fix is in the acceptance script, not in the component.</p><h2 id="collaboration" tabindex="-1">Collaboration <a class="header-anchor" href="#collaboration" aria-label="Permalink to &quot;Collaboration&quot;">​</a></h2><p><code>scripts/collaboration-acceptance.mjs</code> passed its five phases over real stdio MCP and HTTP with zero Host starts: HTTP human and stdio Agent; shared documents, composition and protection; both anchor owners with explicit replies; restart with an event gap and two observers; and a format-3 restore against installed owners. The model-driven variant (<code>RHO_COLLAB_MODEL=1</code>) was not run.</p><h2 id="not-executed" tabindex="-1">Not executed <a class="header-anchor" href="#not-executed" aria-label="Permalink to &quot;Not executed&quot;">​</a></h2><ul><li>The scientific <code>install-acceptance.mjs</code> flows. They require two external example projects (an ordinary analysis and the original paired analysis) that are not present in this environment, so no scientific domain claim is made here.</li><li>The model-driven collaboration variant, and any acceptance that depends on a live external model session.</li><li>npm registry publication and signing. Distribution belongs to a separately selected signed-release milestone; this work published source commits only.</li></ul><h2 id="what-this-does-and-does-not-show" tabindex="-1">What this does and does not show <a class="header-anchor" href="#what-this-does-and-does-not-show" aria-label="Permalink to &quot;What this does and does not show&quot;">​</a></h2><p>It shows the published commits build, pass their source checks, pack into an installable artifact whose recorded hashes verify, and complete the person, execution, recovery, collaboration and UI journeys both from source and from that installed copy.</p><p>It does not show inventory-wide scientific correctness, other platforms, signed or registry distribution, or that every adapter and Skill behaves as documented outside the paths exercised above.</p>',21)])])}const b=t(s,[["render",n]]);export{u as __pageData,b as default};
